// The tie the ordering rule does not cover: a removal hunk and a zero-pre-image
// -line insertion hunk sharing a pre-image start. Target documents that
// "rewriting the patch's layout buys nothing", so both spellings of the one
// change must derive the one target.
func TestATieOnThePreImageStartDoesNotDependOnHunkOrder(t *testing.T) {
	removalFirst := "--- a/app.go\n+++ b/app.go\n@@ -41 +41 @@\n-old\n+new\n" +
		"@@ -41,0 +43,1 @@\n+added\n"
	insertionFirst := "--- a/app.go\n+++ b/app.go\n@@ -41,0 +43,1 @@\n+added\n" +
		"@@ -41 +41 @@\n-old\n+new\n"

	for name, patch := range map[string]string{
		"the removal written first":   removalFirst,
		"the insertion written first": insertionFirst,
	} {
		t.Run(name, func(t *testing.T) {
			files, err := git.ParsePatch(patch)
			require.NoError(t, err)

			target, err := Target(files)
			require.NoError(t, err,
				"the same change spelled two ways derives one target")
			assert.Equal(t, "app.go:41", target)
		})
	}
}

