// A rendered.json holding the JSON literal null is not an object of strings
// either, so it must be refused naming the file rather than read as empty.
func TestARenderedJSONHoldingNullIsRefusedNamingTheFile(t *testing.T) {
	entries, err := DecodeRendered("rendered.json", []byte("null"))

	require.Error(t, err)
	assert.Contains(t, err.Error(), "rendered.json")
	assert.Nil(t, entries)
}

